use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < H : HmacImpl > GenericHkdf < H > { # [doc = " Convenience method for [`extract`][Hkdf::extract] when the generated"] # [doc = " pseudorandom key can be ignored and only HKDF-Expand operation is needed. This is the most"] # [doc = " common constructor."] pub fn new (salt : Option < & [u8] > , ikm : & [u8]) -> Self { let (_ , hkdf) = Self :: extract (salt , ikm) ; hkdf } # [doc = " Create `Hkdf` from an already cryptographically strong pseudorandom key"] # [doc = " as per section 3.3 from RFC5869."] pub fn from_prk (prk : & [u8]) -> Result < Self , InvalidPrkLength > { let hash_len = < H as OutputSizeUser > :: OutputSize :: to_usize () ; if prk . len () < hash_len { return Err (InvalidPrkLength) ; } let hmac = H :: new_from_slice (prk) ; Ok (Self { hmac }) } # [doc = " The RFC5869 HKDF-Extract operation returning both the generated"] # [doc = " pseudorandom key and `Hkdf` struct for expanding."] pub fn extract (salt : Option < & [u8] > , ikm : & [u8]) -> (Output < H > , Self) { let mut extract_ctx = GenericHkdfExtract :: < H > :: new (salt) ; extract_ctx . input_ikm (ikm) ; extract_ctx . finalize () } # [doc = " The RFC5869 HKDF-Expand operation. This is equivalent to calling"] # [doc = " [`expand`][Hkdf::extract] with the `info` argument set equal to the"] # [doc = " concatenation of all the elements of `info_components`."] pub fn expand_multi_info (& self , info_components : & [& [u8]] , okm : & mut [u8] ,) -> Result < () , InvalidLength > { let mut prev : Option < Output < H > > = None ; let chunk_len = < H as OutputSizeUser > :: OutputSize :: USIZE ; if okm . len () > chunk_len * 255 { return Err (InvalidLength) ; } for (block_n , block) in okm . chunks_mut (chunk_len) . enumerate () { let mut hmac = self . hmac . clone () ; if let Some (ref prev) = prev { hmac . update (prev) } for info in info_components { hmac . update (info) ; } hmac . update (& [block_n as u8 + 1]) ; let output = hmac . finalize () ; let block_len = block . len () ; block . copy_from_slice (& output [.. block_len]) ; prev = Some (output) ; } Ok (()) } # [doc = " The RFC5869 HKDF-Expand operation"] # [doc = ""] # [doc = " If you don't have any `info` to pass, use an empty slice."] pub fn expand (& self , info : & [u8] , okm : & mut [u8]) -> Result < () , InvalidLength > { self . expand_multi_info (& [info] , okm) } }
}